package dev.atqiya.ledgerly.reporting.application;
import dev.atqiya.ledgerly.ledger.domain.*; import dev.atqiya.ledgerly.ledger.infrastructure.*; import dev.atqiya.ledgerly.reporting.domain.*; import dev.atqiya.ledgerly.reporting.infrastructure.*; import dev.atqiya.ledgerly.workspace.application.WorkspaceAccessService; import dev.atqiya.ledgerly.workspace.domain.*;
import java.time.Instant; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class CategorizationService{
 private static final Set<WorkspaceRole> MANAGERS=Set.of(WorkspaceRole.OWNER,WorkspaceRole.ADMIN);
 private final CategorizationRuleRepository rules;private final CategoryRepository categories;private final LedgerTransactionRepository transactions;private final WorkspaceAccessService access;
 public CategorizationService(CategorizationRuleRepository r,CategoryRepository c,LedgerTransactionRepository t,WorkspaceAccessService a){rules=r;categories=c;transactions=t;access=a;}
 @Transactional public RuleView create(UUID userId,UUID workspaceId,String name,UUID categoryId,TransactionType type,String contains,int priority){var m=access.requireRole(userId,workspaceId,MANAGERS);var c=categories.findByIdAndWorkspace_Id(categoryId,workspaceId).filter(Category::isActive).orElseThrow(()->new IllegalArgumentException("Category was not found."));if(c.getType()!=type)throw new IllegalArgumentException("Rule and category types must match.");if(priority<1||priority>1000||rules.existsByWorkspace_IdAndPriority(workspaceId,priority))throw new IllegalArgumentException("Rule priority is invalid or already used.");var rule=new CategorizationRule(UUID.randomUUID(),m.getWorkspace(),c,normalize(name),type,normalize(contains),priority,m.getUser(),Instant.now());return RuleView.from(rules.save(rule));}
 @Transactional(readOnly=true) public List<RuleView> list(UUID userId,UUID workspaceId){access.requireMembership(userId,workspaceId);return rules.findAllByWorkspace_IdOrderByPriorityAsc(workspaceId).stream().map(RuleView::from).toList();}
 @Transactional public int apply(UUID userId,UUID workspaceId){var m=access.requireRole(userId,workspaceId,MANAGERS);var active=rules.findAllByWorkspace_IdAndActiveTrueOrderByPriorityAsc(workspaceId);int count=0;for(var t:transactions.findAllByWorkspace_IdAndStatusAndCategoryIsNull(workspaceId,TransactionStatus.POSTED)){var match=active.stream().filter(r->r.matches(t.getDescription(),t.getType())).findFirst();if(match.isPresent()){t.assignCategory(match.get().getCategory(),m.getUser(),Instant.now());count++;}}return count;}
 @Transactional public void disable(UUID userId,UUID workspaceId,UUID ruleId){access.requireRole(userId,workspaceId,MANAGERS);rules.findByIdAndWorkspace_Id(ruleId,workspaceId).orElseThrow(()->new IllegalArgumentException("Rule was not found.")).disable();}
 private String normalize(String value){if(value==null||value.strip().length()<2||value.strip().length()>120)throw new IllegalArgumentException("Rule text must contain between 2 and 120 characters.");return value.strip().replaceAll("\\s+"," ");}
 public record RuleView(UUID id,String name,UUID categoryId,String categoryName,TransactionType type,String descriptionContains,int priority,boolean active){static RuleView from(CategorizationRule r){return new RuleView(r.getId(),r.getName(),r.getCategory().getId(),r.getCategory().getName(),r.getTransactionType(),r.getDescriptionContains(),r.getPriority(),r.isActive());}}
}
